package com.emos.notifications.infrastructure;
import com.emos.notifications.application.DailyDigestService;import com.emos.platform.jobs.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.event.ApplicationReadyEvent;import org.springframework.context.event.EventListener;import org.springframework.stereotype.Component;import tools.jackson.databind.ObjectMapper;import java.time.*;
@Component @ConditionalOnProperty(name="emos.email.enabled",havingValue="true") public class DailyDigestJobHandler implements JobHandler{private final DailyDigestService digest;private final JobRepository jobs;private final ObjectMapper json;private final Clock clock;public DailyDigestJobHandler(DailyDigestService d,JobRepository j,ObjectMapper m,Clock c){digest=d;jobs=j;json=m;clock=c;}public String type(){return "email.daily-digest";}public void handle(Job ignored){digest.sendFor(LocalDate.now(clock));enqueue(LocalDate.now(clock).plusDays(1));}@EventListener(ApplicationReadyEvent.class)void seed(){enqueue(LocalDate.now(clock));}private void enqueue(LocalDate date){jobs.enqueue(type(),"daily-digest:"+date,json.createObjectNode(),date.atStartOfDay(ZoneOffset.UTC).toInstant());}}
